package com.earthtrip.wallet.adapter.out.persistence.record;
import com.earthtrip.wallet.domain.WalletRecord;import jakarta.persistence.*;import java.time.Instant;import java.util.*;
@Entity @Table(name="wallet_records") class WalletRecordJpaEntity{
 @Id @Column(name="id",nullable=false,length=36)private String id;@Column(name="trip_id",nullable=false,length=36)private String tripId;@Column(name="record_type",nullable=false,length=40)private String type;@Column(name="parent_id",length=36)private String parentId;@Column(name="payload",nullable=false,columnDefinition="JSON")private String payload;@Column(name="status",nullable=false,length=40)private String status;@Column(name="visibility",nullable=false,length=20)private String visibility;@Column(name="sort_order",nullable=false)private int sortOrder;@Column(name="created_by",nullable=false,length=36)private String createdBy;@Column(name="updated_by",nullable=false,length=36)private String updatedBy;@Column(name="created_at",nullable=false)private Instant createdAt;@Column(name="updated_at",nullable=false)private Instant updatedAt;@Column(name="deleted_at")private Instant deletedAt;@Version @Column(name="version",nullable=false)private long version;protected WalletRecordJpaEntity(){}WalletRecordJpaEntity(WalletRecord r,String json){id=r.id().toString();apply(r,json);}void apply(WalletRecord r,String json){tripId=r.tripId().toString();type=r.type();parentId=r.parentId()==null?null:r.parentId().toString();payload=json;status=r.status();visibility=r.visibility();sortOrder=r.sortOrder();createdBy=r.createdBy().toString();updatedBy=r.updatedBy().toString();createdAt=r.createdAt();updatedAt=r.updatedAt();deletedAt=r.deletedAt();}String payload(){return payload;}WalletRecord toDomain(Map<String,Object> data){return WalletRecord.restore(UUID.fromString(id),UUID.fromString(tripId),type,parentId==null?null:UUID.fromString(parentId),data,status,visibility,sortOrder,UUID.fromString(createdBy),UUID.fromString(updatedBy),createdAt,updatedAt,deletedAt,version);}}
